create table if not exists production_processes(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),code text not null,name text not null,sequence integer not null,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,code));
create table if not exists production_process_stages(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),production_process_id uuid not null references production_processes(id),code text not null,name text not null,sequence integer not null,source_type text not null check(source_type in('oracle_workbank','oracle_stock','oracle_location','oracle_audit','manual')),capacity_area_code text,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,code));
create table if not exists production_stage_source_rules(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),production_stage_id uuid not null references production_process_stages(id),source_dataset text not null,source_field text not null,match_type text not null check(match_type in('exact','contains','starts_with','ends_with','regex')),match_value text not null,priority integer not null default 100,validation_status text not null default'VALIDATED' check(validation_status in('VALIDATED','REQUIRES_VALIDATION')),active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists screen_print_jobs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),order_no text,job_name text not null,customer_name text,planned_quantity numeric(14,3) not null check(planned_quantity>=0),completed_quantity numeric(14,3) not null default 0 check(completed_quantity>=0),status text not null default'todo' check(status in('todo','in_production','completed','cancelled')),planned_date date,shift_code text,line_name text,started_at timestamptz,completed_at timestamptz,priority integer,notes text,created_by uuid,updated_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(completed_quantity<=planned_quantity));
do $$declare o uuid;d uuid;u uuid;s uuid;st uuid;begin for o in select id from organizations loop insert into production_processes(organization_id,code,name,sequence)values(o,'DTG','DTG',10),(o,'UNDERPRINT','Underprint',20),(o,'SCREEN_PRINT','Screen Print',30)on conflict do nothing;select id into d from production_processes where organization_id=o and code='DTG';select id into u from production_processes where organization_id=o and code='UNDERPRINT';select id into s from production_processes where organization_id=o and code='SCREEN_PRINT';insert into production_process_stages(organization_id,production_process_id,code,name,sequence,source_type,capacity_area_code)values(o,d,'DTG_PICKING','Picking',10,'oracle_workbank','DTG'),(o,d,'DTG_PRINTING','Printing',20,'oracle_workbank','DTG'),(o,d,'DTG_PUTWALL','Putwall',30,'oracle_location','DTG'),(o,d,'DTG_DISPATCH','Dispatch',40,'oracle_audit','DTG'),(o,u,'UP_PICKING','Picking',10,'oracle_stock','UP'),(o,u,'UP_PRINTING','Printing',20,'oracle_location','UP'),(o,u,'UP_DISPATCH','Dispatch',30,'oracle_audit','UP'),(o,s,'SCREEN_TODO','To do',10,'manual','SCREEN_PRINT'),(o,s,'SCREEN_IN_PRODUCTION','In production',20,'manual','SCREEN_PRINT'),(o,s,'SCREEN_COMPLETED','Completed',30,'manual','SCREEN_PRINT')on conflict do nothing;
for st in select id from production_process_stages where organization_id=o loop null;end loop;
insert into production_stage_source_rules(organization_id,production_stage_id,source_dataset,source_field,match_type,match_value,validation_status)select o,id,'workbank','queue','exact','SP11','VALIDATED'from production_process_stages where organization_id=o and code='DTG_PICKING' and not exists(select 1 from production_stage_source_rules where production_stage_id=production_process_stages.id);
insert into production_stage_source_rules(organization_id,production_stage_id,source_dataset,source_field,match_type,match_value,validation_status)select o,id,'workbank','queue','exact','PCOR','VALIDATED'from production_process_stages where organization_id=o and code='DTG_PRINTING' and not exists(select 1 from production_stage_source_rules where production_stage_id=production_process_stages.id);
insert into production_stage_source_rules(organization_id,production_stage_id,source_dataset,source_field,match_type,match_value,validation_status)select o,id,'workbank','from_zone','exact','PWL1','VALIDATED'from production_process_stages where organization_id=o and code='DTG_PUTWALL' and not exists(select 1 from production_stage_source_rules where production_stage_id=production_process_stages.id);
insert into production_stage_source_rules(organization_id,production_stage_id,source_dataset,source_field,match_type,match_value,validation_status)select o,id,'audit','to_location','exact','DTGMOVE','REQUIRES_VALIDATION'from production_process_stages where organization_id=o and code='DTG_DISPATCH' and not exists(select 1 from production_stage_source_rules where production_stage_id=production_process_stages.id);
insert into production_stage_source_rules(organization_id,production_stage_id,source_dataset,source_field,match_type,match_value,validation_status)select o,id,'stock','location','exact','UNDERPRINT','VALIDATED'from production_process_stages where organization_id=o and code='UP_PICKING' and not exists(select 1 from production_stage_source_rules where production_stage_id=production_process_stages.id);
insert into production_stage_source_rules(organization_id,production_stage_id,source_dataset,source_field,match_type,match_value,validation_status)select o,id,'workbank','from_location','ends_with','UP','REQUIRES_VALIDATION'from production_process_stages where organization_id=o and code='UP_PRINTING' and not exists(select 1 from production_stage_source_rules where production_stage_id=production_process_stages.id);
insert into production_stage_source_rules(organization_id,production_stage_id,source_dataset,source_field,match_type,match_value,validation_status)select o,id,'audit','to_location','exact','UPMOVE','REQUIRES_VALIDATION'from production_process_stages where organization_id=o and code='UP_DISPATCH' and not exists(select 1 from production_stage_source_rules where production_stage_id=production_process_stages.id);end loop;end$$;
alter table production_processes enable row level security;alter table production_process_stages enable row level security;alter table production_stage_source_rules enable row level security;alter table screen_print_jobs enable row level security;revoke all on production_processes,production_process_stages,production_stage_source_rules,screen_print_jobs from anon,authenticated;grant all on production_processes,production_process_stages,production_stage_source_rules,screen_print_jobs to service_role;
create index if not exists screen_print_jobs_org_status_idx on screen_print_jobs(organization_id,status,planned_date);create index if not exists process_stage_org_idx on production_process_stages(organization_id,production_process_id,sequence);
